test('partition', () => {
  expect(List.partition((x) => x > 1, [1, 2, 3])).toEqual(Tuple([2, 3], [1]))
  expect(List.partition((x) => x > 1)([1, 2, 3])).toEqual(Tuple([2, 3], [1]))
  expect(List.partition((x) => x > 1, [])).toEqual(Tuple([], []))
  expect(List.partition((x) => x > 1)([])).toEqual(Tuple([], []))
})
